\node[box, fill=gray!8] (acts) at (1.4,-1.75) {residuals\\L9 / L18 / L27};
\node[box, fill=yellow!15] (probe) at (5.0,-1.0) {linear probe\\(+16-token history)};
\node[box, fill=orange!15] (ao) at (5.0,-2.0) {off-the-shelf AO\\``harmful later?''};
\node[box, fill=blue!10] (direct) at (5.0,-3.05) {\direct reader\\encoder $\to$ memory slots};
\node[box, fill=purple!12] (fc) at (9.3,-2.55) {\forecast reader\\4 horizon queries $\to$\\forecast vectors $\to$ timing head};
\node[box, fill=white] (qa) at (9.3,-3.75) {shared QA head\\(question embedding)};
\node[box, fill=green!10] (out) at (13.0,-1.75) {$\hat p(\onset<t{+}H)$\\early-warning alert};
